    #[test]
    fn ts_tests_parse_and_must_be_consistent() {
        let good = r#"{"ts_sha": "abc", "count": 1, "tests": [
            {"key": "v1|f.test.ts|a > b", "project": "v1", "file": "f.test.ts", "title": "a > b"}]}"#;
        let parsed = TsTests::from_json(good).unwrap();
        assert_eq!(parsed.tests[0].title, "a > b");

        let bad_count = good.replace("\"count\": 1", "\"count\": 2");
        assert!(
            TsTests::from_json(&bad_count)
                .unwrap_err()
                .contains("count")
        );

        let bad_key = good.replace(
            "\"key\": \"v1|f.test.ts|a > b\"",
            "\"key\": \"v1|f.test.ts|a\"",
        );
        assert!(
            TsTests::from_json(&bad_key)
                .unwrap_err()
                .contains("v1|f.test.ts|a")
        );

        let one =
            r#"{"key": "v1|f.test.ts|a", "project": "v1", "file": "f.test.ts", "title": "a"}"#;
        let duplicate = format!(r#"{{"ts_sha": "abc", "count": 2, "tests": [{one}, {one}]}}"#);
        assert!(
            TsTests::from_json(&duplicate)
                .unwrap_err()
                .contains("duplicate")
        );
    }

